// Not named $: a global $ here would shadow jQuery for themes that load it
const byId = (id) => document.getElementById(id);

/**
 * ProductOptionsManager - Handles dynamic multi-option price calculation
 * Supports 1-5 option types per product with additive pricing
 */
var ProductOptionsManager = (function() {
    'use strict';

    // Currency symbol: a theme sets window.shopCurrencySign from $shop['currencySign']
    const CUR = window.shopCurrencySign || '£';

    var config = {
        basePrice: 0,
        baseRRP: 0,
        baseWeight: 0,
        taxRate: 20,
        currencySign: CUR,
        optionTypes: [],
        selectors: []
    };

    function init() {
        var configEl = byId('productOptionConfig');
        if (!configEl) return;

        try {
            config.optionTypes = JSON.parse(configEl.value);
        } catch (e) {
            console.error('Failed to parse product option config', e);
            return;
        }

        config.basePrice = parseFloat(byId('productBasePrice')?.value || 0);
        config.baseRRP = parseFloat(byId('productBaseRRP')?.value || 0);
        config.baseWeight = parseFloat(byId('productBaseWeight')?.value || 0);
        config.taxRate = parseFloat(byId('shopTaxRate')?.value || 20);

        config.selectors = document.querySelectorAll('.product-option-select');

        config.selectors.forEach(function(select) {
            select.addEventListener('change', evaluateOptionDependencies);
            select.addEventListener('change', recalculatePrice);
            select.addEventListener('change', swapLinkedImage);
        });

        evaluateOptionDependencies();
        recalculatePrice();
    }

    // Shows/hides option groups that only apply once a specific value is
    // selected elsewhere (e.g. an add-on that only applies to certain
    // controllers). Value ids are unique across the product, so this just
    // checks the current selection set against each group's trigger list -
    // no need to know which select the trigger value lives in.
    function evaluateOptionDependencies() {
        var selectedValueIds = [];
        config.selectors.forEach(function(select) {
            var selectedOption = select.options[select.selectedIndex];
            var valueId = selectedOption.dataset.valueId;
            if (valueId) selectedValueIds.push(valueId);
        });

        document.querySelectorAll('.product-option[data-depends-on-values]').forEach(function(group) {
            var requiredIds = group.dataset.dependsOnValues.split(',');
            var satisfied = requiredIds.some(function(id) {
                return selectedValueIds.indexOf(id) !== -1;
            });

            group.style.display = satisfied ? '' : 'none';
            if (satisfied) return;

            var select = group.querySelector('.product-option-select');
            if (select && select.selectedIndex !== 0) {
                select.selectedIndex = 0; // Reset to Standard/None so a hidden option can't stay selected & charged
            }
        });
    }

    // If the selected option has a linked image slot, swap the main image
    // to match - same src/srcset swap and active-thumbnail toggle that
    // single_custom.min.js's initThumbnail() does on thumbnail hover.
    function swapLinkedImage(event) {
        var selectedOption = event.target.options[event.target.selectedIndex];
        var slot = selectedOption.dataset.linkedImageSlot;
        if (!slot) return;

        var thumb = document.querySelector('.single_product_thumbnails img[data-slot="' + slot + '"]');
        if (!thumb) return;

        document.querySelectorAll('.single_product_thumbnails li').forEach(function(li) {
            li.classList.remove('active');
        });
        thumb.closest('li')?.classList.add('active');

        var singleImage = document.querySelector('.single_product_image');
        if (!singleImage) return;
        singleImage.setAttribute('src', thumb.dataset.image);
        singleImage.setAttribute('srcset', thumb.dataset['image-2x']);
    }

    function recalculatePrice() {
        var totalPremium = 0;
        var totalRRPAdjustment = 0;
        var totalWeight = config.baseWeight;

        config.selectors.forEach(function(select) {
            var selectedOption = select.options[select.selectedIndex];
            var premium = parseFloat(selectedOption.dataset.premium || 0);
            var rrpAdj = parseFloat(selectedOption.dataset.rrp || 0);
            var weight = parseFloat(selectedOption.dataset.weight || 0);

            totalPremium += premium;
            totalRRPAdjustment += rrpAdj;
            totalWeight += weight;
        });

        updateDisplay(totalPremium, totalRRPAdjustment, totalWeight);
    }

    function updateDisplay(totalPremium, totalRRPAdjustment, weight) {
        var vatMultiplier = 1 + (config.taxRate / 100);

        var sellingExc = Math.max(0, config.basePrice + totalPremium).toFixed(2);
        var sellingInc = (sellingExc * vatMultiplier).toFixed(2);
        weight = Math.max(0, weight);

        var rrp = Math.max(0, config.baseRRP + totalRRPAdjustment);
        var rrpInc = (rrp * vatMultiplier).toFixed(2);

        var savingsGBP = (rrpInc - sellingInc).toFixed(2);
        var savingsPC = getSavingsPercent(rrpInc, sellingInc);

        if (byId('exctax')) {
            byId('exctax').innerHTML = CUR + sellingExc + ' <small>excl. VAT</small>';
        }
        if (byId('inctax')) {
            byId('inctax').innerHTML = CUR + sellingInc;
        }
        if (byId('rrp') && rrpInc > 0) {
            byId('rrp').innerHTML = rrpInc;
        }
        if (byId('savings') && savingsGBP > 0) {
            byId('savings').innerHTML = CUR + savingsGBP + ' (' + savingsPC + '%)';
        }
        if (byId('units') && weight > 0) {
            byId('units').value = weight;
        }

        updateProductPR(sellingExc);
    }

    function updateProductPR(totalPrice) {
        var productTitle = byId('productTitle')?.value || '';
        var baseRef = byId('productBaseRef')?.value || '';
        var refs = [];
        var firstOptionHandled = false;

        config.selectors.forEach(function(select) {
            var selectedOption = select.options[select.selectedIndex];
            var ref = selectedOption.dataset.reference || '';

            if (!firstOptionHandled) {
                // First option: use selected ref if available, otherwise base ref
                refs.push(ref || baseRef);
                firstOptionHandled = true;
            } else if (ref) {
                // Additional options: only add if a ref exists
                refs.push(ref);
            }
        });

        // If no selectors, just use base ref
        if (refs.length === 0) {
            refs.push(baseRef);
        }

        var combinedRef = refs.join(' / ');
        var productprValue = productTitle + ' (' + combinedRef + '): ' + totalPrice;

        if (byId('productpr')) {
            byId('productpr').value = productprValue;
        }
    }

    return {
        init: init,
        recalculate: recalculatePrice
    };
})();

function getSavingsPercent(originalPrice, discountedPrice) {
    originalPrice = parseFloat(originalPrice);
    discountedPrice = parseFloat(discountedPrice);
    if (originalPrice <= 0 || discountedPrice <= 0) return 0;
    const savings = originalPrice - discountedPrice;
    return Math.round((savings / originalPrice) * 100);
}

document.addEventListener('DOMContentLoaded', function() {
    ProductOptionsManager.init();

    // Linked product expandable sections
    document.querySelectorAll('.linked-product-toggle').forEach(function(toggle) {
        toggle.addEventListener('click', function(e) {
            e.preventDefault();
            var targetId = this.dataset.target;
            var targetEl = document.getElementById(targetId);

            if (targetEl) {
                targetEl.style.display = targetEl.style.display === 'none' ? 'block' : 'none';
            }
        });
    });
});

// Legacy support
function ProductOptions(StandardPrice, StandardRRP, StandardWeight, OptionPremiums, OptionRRPs, OptionWeights, vatPercent) {
    const vatrate = vatPercent / 100 + 1;
    const standardElement = byId("standard0");

    if (standardElement && standardElement.selected) {
        const rrpInc = (StandardRRP * vatrate).toFixed(2);
        const sellingExc = parseFloat(StandardPrice).toFixed(2);
        const sellingInc = (sellingExc * vatrate).toFixed(2);
        const savingsGBP = Math.max(rrpInc - sellingInc, 0).toFixed(2);
        const savingsPercent = getSavingsPercent(rrpInc, sellingInc);
        updateHTML(sellingExc, sellingInc, rrpInc, savingsGBP, savingsPercent, StandardWeight);
    } else {
        const optionPrices = OptionPremiums.split(",");
        const optionRRPs = OptionRRPs.split(",");
        const optionWeights = OptionWeights.split(",");

        for (let i = 0; i < optionPrices.length; i++) {
            const optionElement = byId("option" + (i + 1));
            if (optionElement && optionElement.selected) {
                const rrpInc = (optionRRPs[i] * vatrate).toFixed(2);
                const sellingExc = (parseFloat(StandardPrice) + parseFloat(optionPrices[i])).toFixed(2);
                const sellingInc = (sellingExc * vatrate).toFixed(2);
                const savingsGBP = Math.max(rrpInc - sellingInc, 0).toFixed(2);
                const savingsPercent = Math.max(getSavingsPercent(rrpInc, sellingInc), 0);
                updateHTML(sellingExc, sellingInc, rrpInc, savingsGBP, savingsPercent, optionWeights[i]);
                break;
            }
        }
    }
}

function updateHTML(sellingExcTax, sellingIncTax, rrpIncTax, savingsGBP, savingsPercent, weight) {
    if (byId("exctax")) byId("exctax").innerHTML = `${CUR}${sellingExcTax} <small>excl. VAT</small>`;
    if (byId("inctax")) byId("inctax").innerHTML = `${CUR}${sellingIncTax}`;
    if (byId("rrp")) byId("rrp").innerHTML = rrpIncTax;
    if (byId("savings")) byId("savings").innerHTML = `${CUR}${savingsGBP} (${savingsPercent}%)`;
    if (byId("units") && weight > 0) byId("units").value = weight;
}
